const expectedTargets=read('membership-targets.json');const collectedTargets=new Set();for(const file of fs.readdirSync(root+'/sources').filter(f=>/^memberships-\d+\.manifest\.json$/.test(f))){const manifest=read('sources/'+file);const payload=read('sources/'+file.replace('.manifest',''));if(!payload.results?.bindings||payload.results.bindings.length>=2400)throw Error('Incomplete membership batch '+file);for(const id of manifest.teams)collectedTargets.add(id);}if(expectedTargets.some(t=>!collectedTargets.has(t.id)))throw Error('Missing membership batches; previous snapshots must remain active');
let rows=[];for(const f of fs.readdirSync(root+'/sources').filter(f=>/^memberships-\d+\.json$/.test(f))){const data=read('sources/'+f);rows.push(...data.results.bindings.map(r=>({...r,sourceFile:f})));}
const posMap=[[/^(g|gk|goalkeeper|association football goalkeeper|football goalkeeper)$/i,'G'],[/^(d|defender|centre-back|center-back|left-back|right-back|full-back|fullback|wing-back|association football defender|central defender)$/i,'D'],[/^(m|midfielder|defensive midfielder|central midfielder|attacking midfielder|defensive midfield|attacking midfield|association football midfielder)$/i,'M'],[/^(a|forward|striker|winger|centre-forward|center-forward|left winger|right winger|second striker|association football forward)$/i,'A']];
